package kr.workbench;
import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Bounded OpenAPI metadata. Templates never become network requests until resolved by a reviewer. */
final class ApiInventory {
 record Endpoint(String url,String method,Set<String> query,Set<String> body,Set<String> headers,String contentType,String note){
  boolean template(){return url.contains("{")||url.contains("}");}
  boolean matches(String actual){try{String path=URI.create(actual).getRawPath(),p=url.substring(url.indexOf('/',url.indexOf("://")+3));StringBuilder regex=new StringBuilder("^");for(String s:p.split("/",-1)){if(regex.length()>1)regex.append('/');regex.append(s.matches("\\{[^}]+}")?"[^/]+":java.util.regex.Pattern.quote(s));}return path.matches(regex+"$")&&origin(url).equals(origin(actual));}catch(Exception e){return false;}}
 }
 static String origin(String url){int end=url.indexOf('/',url.indexOf("://")+3);return end<0?url:url.substring(0,end);}
 static List<Endpoint> parse(String body,String source){
  Object object;try{object=MinerJson.parse(body,2*1024*1024,60000);}catch(Exception e){return List.of();}if(!(object instanceof Map<?,?> doc)||!(doc.get("openapi") instanceof String||doc.get("swagger") instanceof String)||!(doc.get("paths") instanceof Map<?,?> paths))return List.of();
  String base=ActivityTracker.safeUrl(source);if(base==null)return List.of();String origin=origin(base),prefix="";
  if(doc.get("servers") instanceof List<?> servers&&!servers.isEmpty()&&servers.get(0) instanceof Map<?,?> server&&server.get("url") instanceof String value){try{URI u=URI.create(origin+"/").resolve(value);if(u.getUserInfo()!=null||!origin.equals(origin(u.toString()))||u.getQuery()!=null||u.getFragment()!=null)return List.of();prefix=u.getRawPath().replaceAll("/+$","");}catch(Exception e){return List.of();}}
  else if(doc.get("basePath") instanceof String path&&path.startsWith("/"))prefix=path.replaceAll("/+$","");
  List<Endpoint> out=new ArrayList<>();for(var entry:paths.entrySet()){
   String path=entry.getKey().toString();if(!path.startsWith("/")||path.length()>2048||path.contains("?")||path.contains("#")||!(entry.getValue() instanceof Map<?,?> raw))continue;Map<?,?> item=resolve(raw,doc,0);
   for(String method:List.of("get","head","options","post","put","patch","delete")){Object op=item.get(method);if(!(op instanceof Map<?,?> opRaw))continue;Map<?,?> operation=resolve(opRaw,doc,0);Set<String> query=new TreeSet<>(),fields=new TreeSet<>(),headers=new TreeSet<>();parameters(item.get("parameters"),doc,query,headers);parameters(operation.get("parameters"),doc,query,headers);
    String type="";Object requestBody=operation.get("requestBody");if(requestBody instanceof Map<?,?> rb){Map<?,?> content=resolve(rb,doc,0).get("content") instanceof Map<?,?> c?c:Map.of();for(String candidate:List.of("application/json","application/x-www-form-urlencoded","multipart/form-data"))if(content.get(candidate) instanceof Map<?,?> value){type=candidate;properties(value.get("schema"),doc,fields,0);break;}}
    if(operation.get("parameters") instanceof List<?> ps)for(Object p:ps)if(p instanceof Map<?,?> parameter){Map<?,?> resolved=resolve(parameter,doc,0);if("body".equals(resolved.get("in"))){properties(resolved.get("schema"),doc,fields,0);if(type.isEmpty())type="application/json";}else if("formData".equals(resolved.get("in"))&&resolved.get("name") instanceof String name){fields.add(name);type="application/x-www-form-urlencoded";}}
    String url=origin+prefix+path;if(out.size()>=500)return List.copyOf(out);out.add(new Endpoint(url,method.toUpperCase(Locale.ROOT),Set.copyOf(query),Set.copyOf(fields),Set.copyOf(headers),type,"OpenAPI 문서 · 실행/인증 미검증"));
   }
  }return List.copyOf(out);
 }
 private static Map<?,?> resolve(Map<?,?> item,Map<?,?> doc,int depth){if(depth>8)return Map.of();if(!(item.get("$ref") instanceof String ref))return item;if(!ref.startsWith("#/"))return Map.of();Object node=doc;for(String part:ref.substring(2).split("/")){if(!(node instanceof Map<?,?> map))return Map.of();node=map.get(part.replace("~1","/").replace("~0","~"));}return node instanceof Map<?,?> map?resolve(map,doc,depth+1):Map.of();}
 private static void parameters(Object ps,Map<?,?> doc,Set<String> query,Set<String> headers){if(!(ps instanceof List<?> rows))return;for(Object row:rows)if(row instanceof Map<?,?> raw){Map<?,?> p=resolve(raw,doc,0);if(p.get("name") instanceof String name&&validName(name)){if("query".equals(p.get("in"))&&query.size()<64)query.add(name);if("header".equals(p.get("in"))&&headers.size()<64)headers.add(name);}}}
 private static boolean validName(String name){return !name.isBlank()&&name.length()<=128&&name.chars().noneMatch(c->c<32);}
 private static void properties(Object schema,Map<?,?> doc,Set<String> fields,int depth){if(depth>8||!(schema instanceof Map<?,?> raw))return;Map<?,?> item=resolve(raw,doc,0);if(item.get("properties") instanceof Map<?,?> ps)for(Object key:ps.keySet())if(fields.size()<64&&validName(key.toString()))fields.add(key.toString());if(item.get("allOf") instanceof List<?> rows)for(Object row:rows)properties(row,doc,fields,depth+1);}
 static JsRequestDraft.Draft draft(Endpoint e,String resolved){String target=resolved.strip();if(target.contains("{")||target.contains("}")||!origin(e.url).equals(origin(target)))throw new IllegalArgumentException("같은 Origin의 템플릿 변수를 확정하세요.");URI u=URI.create(target);if(u.getPath().contains("{")||u.getPath().contains("}")||u.getUserInfo()!=null||u.getHost()==null||u.getFragment()!=null||u.getQuery()!=null||!Set.of("http","https").contains(u.getScheme()))throw new IllegalArgumentException("HTTP(S) 경로만 입력하세요. 쿼리값은 복사하지 않습니다.");StringJoiner query=new StringJoiner("&");for(String name:new TreeSet<>(e.query))query.add(URLEncoder.encode(name,StandardCharsets.UTF_8)+"=REPLACE_ME");Map<String,Object> data=new TreeMap<>();for(String name:e.body)data.put(name,"REPLACE_ME");String body=e.contentType.equals("application/x-www-form-urlencoded")?form(data):data.isEmpty()?"":MetadataExport.json(data);return new JsRequestDraft.Draft(target+(query.length()==0?"":"?"+query),e.method,body,e.contentType.isEmpty()?"application/json":e.contentType);}
 private static String form(Map<String,Object> fields){StringJoiner out=new StringJoiner("&");for(String name:fields.keySet())out.add(URLEncoder.encode(name,StandardCharsets.UTF_8)+"=REPLACE_ME");return out.toString();}
}
